import type { GamepadBindings, GamepadLabelLayout } from "./types";

export type GamepadAction = keyof GamepadBindings;
export type GamepadPhase = "library" | "question" | "answer" | "paused" | "hidden-complete";

export const DEFAULT_BINDINGS: GamepadBindings = {
  reveal: 0,
  again: 1,
  hard: 2,
  good: 0,
  easy: 3,
  undo: 4,
  pause: 9,
  hideToday: 8,
  scrollUp: 12,
  scrollDown: 13,
};

export const GAMEPAD_ACTION_LABELS: Record<GamepadAction, string> = {
  reveal: "答えを表示",
  again: "不正解",
  hard: "難しい",
  good: "正解",
  easy: "簡単",
  undo: "1つ戻す",
  pause: "一時停止",
  hideToday: "今日は非表示",
  scrollUp: "カードを上へスクロール",
  scrollDown: "カードを下へスクロール",
};

type ResolvedGamepadLabelLayout = Exclude<GamepadLabelLayout, "auto">;

const BUTTON_LABELS: Record<ResolvedGamepadLabelLayout, string[]> = {
  // iPadで確認した8BitDo系の配列。ABだけが標準Gamepad配列と逆になる機種向け。
  "ab-swap": ["B", "A", "X", "Y", "L", "R", "ZL", "ZR", "SELECT", "START", "L3", "R3", "↑", "↓", "←", "→"],
  xbox: ["A", "B", "X", "Y", "LB", "RB", "LT", "RT", "表示", "メニュー", "L3", "R3", "↑", "↓", "←", "→"],
  nintendo: ["B", "A", "Y", "X", "L", "R", "ZL", "ZR", "−", "+", "L3", "R3", "↑", "↓", "←", "→"],
  playstation: ["×", "○", "□", "△", "L1", "R1", "L2", "R2", "作成", "OPTIONS", "L3", "R3", "↑", "↓", "←", "→"],
};

export function resolveGamepadLabelLayout(layout: GamepadLabelLayout, gamepadId = ""): ResolvedGamepadLabelLayout {
  if (layout !== "auto") return layout;
  const id = gamepadId.toLowerCase();
  if (/8bitdo/.test(id)) return "ab-swap";
  if (/nintendo|switch|joy-con|joycon/.test(id)) return "nintendo";
  if (/dualshock|dualsense|playstation|sony/.test(id)) return "playstation";
  return "xbox";
}

export function gamepadButtonLabel(index: number, layout: GamepadLabelLayout, gamepadId = ""): string {
  const resolved = resolveGamepadLabelLayout(layout, gamepadId);
  return BUTTON_LABELS[resolved][index] ?? `#${index}`;
}

export function gamepadActionFor(
  phase: GamepadPhase,
  bindings: GamepadBindings,
  buttonIndex: number,
): GamepadAction | undefined {
  if (buttonIndex === bindings.pause) return "pause";
  if (buttonIndex === bindings.undo) return "undo";
  if (phase === "hidden-complete" && buttonIndex === bindings.hideToday) return "hideToday";
  if ((phase === "question" || phase === "answer") && buttonIndex === bindings.hideToday) return "hideToday";
  if (phase !== "library" && phase !== "paused" && buttonIndex === bindings.scrollUp) return "scrollUp";
  if (phase !== "library" && phase !== "paused" && buttonIndex === bindings.scrollDown) return "scrollDown";
  if (phase === "question" && buttonIndex === bindings.reveal) return "reveal";
  if (phase === "answer") {
    const grades: GamepadAction[] = ["again", "hard", "good", "easy"];
    return grades.find((action) => bindings[action] === buttonIndex);
  }
  return undefined;
}

interface GamepadStatus {
  connected: boolean;
  id?: string;
  index?: number;
  pressed: number[];
}

type ActionHandler = (action: GamepadAction, buttonIndex: number) => void;
type StatusHandler = (status: GamepadStatus) => void;

export class GamepadController {
  private animationFrame = 0;
  private previous = new Map<number, boolean[]>();
  private lastTriggered = new Map<number, number>();
  private captureHandler?: (buttonIndex: number) => void;
  private phase: GamepadPhase = "library";
  private bindings: GamepadBindings;
  private haptics = true;
  private lastStatusKey = "";

  constructor(
    bindings: GamepadBindings,
    private readonly onAction: ActionHandler,
    private readonly onStatus: StatusHandler,
  ) {
    this.bindings = { ...bindings };
  }

  start(): void {
    if (this.animationFrame) return;
    const loop = (timestamp: number) => {
      this.animationFrame = requestAnimationFrame(loop);
      try {
        this.poll(timestamp);
      } catch {
        // Safari can transiently fail while a controller reconnects or the PWA
        // returns from the background. Keep the next animation frame alive.
        this.reportDisconnected();
      }
    };
    this.animationFrame = requestAnimationFrame(loop);
  }

  stop(): void {
    cancelAnimationFrame(this.animationFrame);
    this.animationFrame = 0;
    this.previous.clear();
    this.lastTriggered.clear();
    this.lastStatusKey = "";
  }

  setBindings(bindings: GamepadBindings): void {
    this.bindings = { ...bindings };
  }

  setPhase(phase: GamepadPhase): void {
    this.phase = phase;
  }

  setHaptics(enabled: boolean): void {
    this.haptics = enabled;
  }

  captureNextButton(handler: (buttonIndex: number) => void): void {
    this.captureHandler = handler;
  }

  cancelCapture(): void {
    this.captureHandler = undefined;
  }

  private poll(timestamp: number): void {
    const pads = this.readGamepads();
    const primary = pads[0];
    const pressed = primary?.buttons.flatMap((button, index) => (button.pressed ? [index] : [])) ?? [];
    const statusKey = `${primary?.index ?? "none"}:${pressed.join(",")}`;
    if (statusKey !== this.lastStatusKey) {
      this.lastStatusKey = statusKey;
      this.onStatus({ connected: Boolean(primary), id: primary?.id, index: primary?.index, pressed });
    }

    for (const pad of pads) {
      const previous = this.previous.get(pad.index) ?? [];
      const current = pad.buttons.map((button) => button.pressed);
      for (let index = 0; index < current.length; index += 1) {
        if (!current[index]) continue;
        const newlyPressed = !previous[index];
        const action = gamepadActionFor(this.phase, this.bindings, index);
        const repeatable = action === "scrollUp" || action === "scrollDown";
        if (!newlyPressed && !repeatable) continue;
        const last = this.lastTriggered.get(index) ?? -Infinity;
        if (timestamp - last < (repeatable ? 220 : 140)) continue;
        this.lastTriggered.set(index, timestamp);
        if (this.captureHandler && newlyPressed) {
          const handler = this.captureHandler;
          this.captureHandler = undefined;
          handler(index);
          continue;
        }
        if (action) {
          this.onAction(action, index);
          void this.pulse(pad, action === "again" ? 0.28 : 0.11);
        }
      }
      this.previous.set(pad.index, current);
    }

    for (const index of [...this.previous.keys()]) {
      if (!pads.some((pad) => pad.index === index)) this.previous.delete(index);
    }
  }

  private readGamepads(): Gamepad[] {
    try {
      if (typeof navigator.getGamepads !== "function") return [];
      return Array.from(navigator.getGamepads()).filter((pad): pad is Gamepad => Boolean(pad));
    } catch {
      return [];
    }
  }

  private reportDisconnected(): void {
    const statusKey = "none:";
    if (statusKey === this.lastStatusKey) return;
    this.lastStatusKey = statusKey;
    this.onStatus({ connected: false, pressed: [] });
  }

  private async pulse(gamepad: Gamepad, magnitude: number): Promise<void> {
    if (!this.haptics) return;
    const actuator = gamepad.vibrationActuator;
    if (!actuator || typeof actuator.playEffect !== "function") return;
    try {
      await actuator.playEffect("dual-rumble", {
        duration: 42,
        startDelay: 0,
        strongMagnitude: magnitude,
        weakMagnitude: magnitude,
      });
    } catch {
      // Haptics are optional and controller-dependent.
    }
  }
}
