const DB_NAME = "anki-sprint-local";
const DB_VERSION = 6;

let databasePromise: Promise<IDBDatabase> | undefined;

function requestValue<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("IndexedDB request failed"));
  });
}

function transactionDone(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("IndexedDB transaction failed"));
    transaction.onabort = () => reject(transaction.error ?? new Error("IndexedDB transaction aborted"));
  });
}

export function openDatabase(): Promise<IDBDatabase> {
  if (databasePromise) return databasePromise;

  databasePromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    let abandoned = false;
    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains("decks")) db.createObjectStore("decks", { keyPath: "id" });
      if (!db.objectStoreNames.contains("cards")) {
        const cards = db.createObjectStore("cards", { keyPath: "key" });
        cards.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("media")) {
        const media = db.createObjectStore("media", { keyPath: "key" });
        media.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("reviews")) {
        const reviews = db.createObjectStore("reviews", { keyPath: "id", autoIncrement: true });
        reviews.createIndex("deckId", "deckId", { unique: false });
        reviews.createIndex("deckCard", ["deckId", "cardId"], { unique: false });
      }
      if (!db.objectStoreNames.contains("progress")) {
        const progress = db.createObjectStore("progress", { keyPath: "key" });
        progress.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("settings")) db.createObjectStore("settings", { keyPath: "key" });
      if (!db.objectStoreNames.contains("sessions")) db.createObjectStore("sessions", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("imports")) db.createObjectStore("imports", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("reviewFlags")) {
        const reviewFlags = db.createObjectStore("reviewFlags", { keyPath: "key" });
        reviewFlags.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("dailyNew")) db.createObjectStore("dailyNew", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("dailyReview")) db.createObjectStore("dailyReview", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("todayOnlyLimits")) {
        const todayOnlyLimits = db.createObjectStore("todayOnlyLimits", { keyPath: "scopeKey" });
        todayOnlyLimits.createIndex("deckId", "deckId", { unique: false });
      }
    };
    request.onsuccess = () => {
      const db = request.result;
      if (abandoned) {
        db.close();
        return;
      }
      db.onversionchange = () => {
        db.close();
        databasePromise = undefined;
      };
      db.onclose = () => {
        databasePromise = undefined;
      };
      resolve(db);
    };
    request.onerror = () => {
      abandoned = true;
      databasePromise = undefined;
      reject(request.error ?? new Error("IndexedDB could not be opened"));
    };
    request.onblocked = () => {
      abandoned = true;
      databasePromise = undefined;
      reject(new Error("別の画面がデータベースを使用中です。ほかの画面を閉じてください。"));
    };
  });

  return databasePromise;
}

export async function getDecks(): Promise<DeckRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("decks", "readonly");
  const values = await requestValue(transaction.objectStore("decks").getAll() as IDBRequest<DeckRecord[]>);
  return values.sort(compareDeckNames);
}

