export async function undoLastReview(
  deckId: string,
  savedSession?: SavedSessionRecord,
  eligibleCardIds?: ReadonlySet<string>,
  expectedReviewId?: number,
): Promise<ReviewRecord | undefined> {
  const db = await openDatabase();
  const transaction = db.transaction(["reviews", "progress", "decks", "sessions"], "readwrite");
  if (savedSession) await putSessionIfNewer(transaction.objectStore("sessions"), savedSession);
  const reviewStore = transaction.objectStore("reviews");
  const index = reviewStore.index("deckId");
  const latest = await latestReviewFromIndex(index, deckId, eligibleCardIds);
  if (!latest?.id || (expectedReviewId !== undefined && latest.id !== expectedReviewId)) {
    transaction.abort();
    return undefined;
  }
  reviewStore.delete(latest.id);

  const progressStore = transaction.objectStore("progress");
  const progressKey = `${deckId}:${latest.cardId}`;
  const progress = await requestValue(progressStore.get(progressKey) as IDBRequest<ProgressRecord | undefined>);
  if (progress) {
    const remaining = await requestValue(
      reviewStore.index("deckCard").getAll(IDBKeyRange.only([deckId, latest.cardId])) as IDBRequest<ReviewRecord[]>,
    );
    const validRemaining = remaining.filter((review) => review.id !== latest.id);
    const repairedProgress = progressFromReviewHistory(deckId, latest.cardId, validRemaining);
    if (!repairedProgress) {
      // Repair stale progress as part of Undo instead of carrying an
      // inconsistent reviewCount/dueAt forward forever.
      progressStore.delete(progressKey);
    } else {
      progressStore.put(repairedProgress);
    }
  }

  const deckStore = transaction.objectStore("decks");
  const deck = await requestValue(deckStore.get(deckId) as IDBRequest<DeckRecord | undefined>);
  if (deck) {
    deck.reviewCount = Math.max(0, deck.reviewCount - 1);
    if (latest.grade === "good" || latest.grade === "easy") deck.correctCount = Math.max(0, deck.correctCount - 1);
    deckStore.put(deck);
  }
  await transactionDone(transaction);
  return latest;
}

export async function clearDeckProgress(deckId: string): Promise<void> {
  const db = await openDatabase();
  const transaction = db.transaction(["reviews", "progress", "decks", "sessions", "dailyNew", "dailyReview"], "readwrite");
  transaction.objectStore("sessions").delete(deckId);
  transaction.objectStore("dailyNew").delete(deckId);
  transaction.objectStore("dailyReview").delete(deckId);
  await Promise.all([
    deleteByDeckIndex(transaction.objectStore("reviews"), deckId),
    deleteByDeckIndex(transaction.objectStore("progress"), deckId),
  ]);
  const deckStore = transaction.objectStore("decks");
  const deck = await requestValue(deckStore.get(deckId) as IDBRequest<DeckRecord | undefined>);
  if (deck) {
    deck.reviewCount = 0;
    deck.correctCount = 0;
    delete deck.lastStudiedAt;
    deckStore.put(deck);
  }
  await transactionDone(transaction);
}

export async function getDailyNewState(deckId: string, dayStartedAt: number): Promise<DailyNewStateRecord> {
  const db = await openDatabase();
  const transaction = db.transaction("dailyNew", "readwrite");
  const store = transaction.objectStore("dailyNew");
  const current = await requestValue(store.get(deckId) as IDBRequest<DailyNewStateRecord | undefined>);
  const state = current?.dayStartedAt === dayStartedAt
    ? current
    : { deckId, dayStartedAt, cardIds: [], updatedAt: Date.now() } satisfies DailyNewStateRecord;
  if (state !== current) store.put(state);
  await transactionDone(transaction);
  return state;
}

export async function markDailyNewCard(
  deckId: string,
  cardId: string,
  dayStartedAt: number,
  introducedAt = Date.now(),
): Promise<DailyNewStateRecord> {
  const db = await openDatabase();
  const transaction = db.transaction("dailyNew", "readwrite");
  const store = transaction.objectStore("dailyNew");
  const current = await requestValue(store.get(deckId) as IDBRequest<DailyNewStateRecord | undefined>);
  const cardIds = current?.dayStartedAt === dayStartedAt ? [...current.cardIds] : [];
  if (!cardIds.includes(cardId)) cardIds.push(cardId);
  const state: DailyNewStateRecord = { deckId, dayStartedAt, cardIds, updatedAt: introducedAt };
  store.put(state);
  await transactionDone(transaction);
  return state;
}

