import { decompress } from "fzstd";

const UTF8 = new TextDecoder("utf-8", { fatal: true });
const ZSTD_MAGIC = 0xfd2fb528;

export interface ModernMediaMapEntry {
  name: string;
  zipEntryName: string;
  expectedSize?: number;
}

class ProtoReader {
  private offset = 0;

  constructor(private readonly bytes: Uint8Array) {}

  get done(): boolean {
    return this.offset >= this.bytes.length;
  }

  readTag(): { field: number; wire: number } {
    const tag = this.readVarint();
    if (!tag) throw new Error("invalid protobuf tag");
    return { field: Math.floor(tag / 8), wire: tag & 7 };
  }

  readVarint(): number {
    const value = this.readVarintBigInt();
    if (value > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error("protobuf integer is too large");
    return Number(value);
  }

  private readVarintBigInt(): bigint {
    let value = 0n;
    let shift = 0n;
    for (let index = 0; index < 10; index += 1) {
      if (this.offset >= this.bytes.length) throw new Error("truncated protobuf varint");
      const byte = this.bytes[this.offset++];
      if (index === 9 && byte > 1) throw new Error("invalid protobuf varint");
      value |= BigInt(byte & 0x7f) << shift;
      if ((byte & 0x80) === 0) return value;
      shift += 7n;
    }
    throw new Error("invalid protobuf varint");
  }

  readBytes(): Uint8Array {
    const length = this.readVarint();
    const end = this.offset + length;
    if (length < 0 || end > this.bytes.length) throw new Error("truncated protobuf bytes");
    const value = this.bytes.subarray(this.offset, end);
    this.offset = end;
    return value;
  }

  readString(): string {
    return UTF8.decode(this.readBytes());
  }

  skip(wire: number): void {
    if (wire === 0) {
      this.readVarintBigInt();
      return;
    }
    if (wire === 1) {
      this.advance(8);
      return;
    }
    if (wire === 2) {
      this.advance(this.readVarint());
      return;
    }
    if (wire === 5) {
      this.advance(4);
      return;
    }
    throw new Error("unsupported protobuf wire type");
  }

  private advance(length: number): void {
    const end = this.offset + length;
    if (length < 0 || end > this.bytes.length) throw new Error("truncated protobuf field");
    this.offset = end;
  }
}

function littleEndian(bytes: Uint8Array, offset: number, length: number): bigint {
  if (offset < 0 || length < 0 || offset + length > bytes.length) throw new Error("truncated zstd header");
  let value = 0n;
  for (let index = 0; index < length; index += 1) {
    value |= BigInt(bytes[offset + index]) << BigInt(index * 8);
  }
  return value;
}

function checkZstdAllocation(bytes: Uint8Array, maximumBytes: number): void {
  if (bytes.length < 5) throw new Error("truncated zstd frame");
  const magic = Number(littleEndian(bytes, 0, 4));
  if (magic !== ZSTD_MAGIC) throw new Error("invalid zstd frame");

  const flag = bytes[4];
  if (flag & 8) throw new Error("invalid zstd frame flags");
  const singleSegment = (flag >> 5) & 1;
  const dictionaryFlag = flag & 3;
  const contentFlag = flag >> 6;
  let offset = 6 - singleSegment;
  offset += dictionaryFlag === 3 ? 4 : dictionaryFlag;
  const contentSizeBytes = contentFlag ? 1 << contentFlag : singleSegment;
  let contentSize = contentSizeBytes ? littleEndian(bytes, offset, contentSizeBytes) : 0n;
  if (contentFlag === 1) contentSize += 256n;

  let windowSize = contentSize;
  if (!singleSegment) {
    if (bytes.length < 6) throw new Error("truncated zstd window descriptor");
    const descriptor = bytes[5];
    const base = 1n << BigInt(10 + (descriptor >> 3));
    windowSize = base + (base >> 3n) * BigInt(descriptor & 7);
  }
  const limit = BigInt(maximumBytes);
  if (contentSize > limit || windowSize > limit) throw new Error("zstd output exceeds the safety limit");
}

export function decompressZstd(bytes: Uint8Array, maximumBytes: number, expectedSize?: number): Uint8Array {
  checkZstdAllocation(bytes, maximumBytes);
  const output = decompress(bytes);
  if (output.byteLength > maximumBytes) throw new Error("zstd output exceeds the safety limit");
  if (expectedSize !== undefined && output.byteLength !== expectedSize) {
    throw new Error("zstd output size does not match the media map");
  }
  return output;
}

export function parseLegacyMediaMap(bytes: Uint8Array): Record<string, string> {
  const text = UTF8.decode(bytes).replace(/^\uFEFF/, "").trim();
  const parsed = JSON.parse(text) as unknown;
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("media map is not an object");
  const mediaMap: Record<string, string> = {};
  for (const [entryName, fileName] of Object.entries(parsed)) {
    if (typeof fileName !== "string") throw new Error("media map contains a non-string filename");
    mediaMap[entryName] = fileName;
  }
  return mediaMap;
}

function parseModernMediaEntry(bytes: Uint8Array, index: number): ModernMediaMapEntry {
  const reader = new ProtoReader(bytes);
  let name = "";
  let expectedSize: number | undefined;
  let legacyZipFilename: number | undefined;
  while (!reader.done) {
    const { field, wire } = reader.readTag();
    if (field === 1 && wire === 2) name = reader.readString();
    else if (field === 2 && wire === 0) expectedSize = reader.readVarint();
    else if (field === 255 && wire === 0) legacyZipFilename = reader.readVarint();
    else reader.skip(wire);
  }
  if (!name) throw new Error("media entry has no filename");
  return {
    name,
    zipEntryName: String(legacyZipFilename ?? index),
    expectedSize,
  };
}

export function parseModernMediaMap(bytes: Uint8Array): ModernMediaMapEntry[] {
  const reader = new ProtoReader(bytes);
  const entries: ModernMediaMapEntry[] = [];
  while (!reader.done) {
    const { field, wire } = reader.readTag();
    if (field === 1 && wire === 2) entries.push(parseModernMediaEntry(reader.readBytes(), entries.length));
    else reader.skip(wire);
  }
  return entries;
}

export function parseModernNotetypeConfig(bytes: Uint8Array): { modelType: number; css: string } {
  const reader = new ProtoReader(bytes);
  let modelType = 0;
  let css = "";
  while (!reader.done) {
    const { field, wire } = reader.readTag();
    if (field === 1 && wire === 0) modelType = reader.readVarint();
    else if (field === 3 && wire === 2) css = reader.readString();
    else reader.skip(wire);
  }
  return { modelType, css };
}

export function parseModernTemplateConfig(bytes: Uint8Array): { question: string; answer: string } {
  const reader = new ProtoReader(bytes);
  let question = "";
  let answer = "";
  while (!reader.done) {
    const { field, wire } = reader.readTag();
    if (field === 1 && wire === 2) question = reader.readString();
    else if (field === 2 && wire === 2) answer = reader.readString();
    else reader.skip(wire);
  }
  return { question, answer };
}
